79	// A fixture whose first message is a hello carries its own site; the rest were cut from the middle
80	// of a run and are replayed after this site's hello, as the tests do (test/helpers/fixtures.ts).
81	function ownHello(records: FixtureRecord[]): boolean {
82	  const first = records.filter((r) => r.kind === 'msg').sort((a, b) => a.rx_ms! - b.rx_ms!)[0];
83	  return (first?.m as { type?: string } | undefined)?.type === 'hello';
84	}
