90	export class Player {
91	  readonly #dir: URL;
92	  #info!: FixtureInfo;
93	  #records: FixtureRecord[] = [];
94	  #r!: Replayer;
95	  #playing = false;
96	  #speed = 1;
97	  #bookmarks: Bookmark[] = [];
98	  #heartbeats = false;
99	
100	  constructor(fixture: string, dir: URL = FIXTURES_DIR) {
101	    this.#dir = dir;
102	    this.load(fixture);
103	  }
104	
105	  load(name: string): void {
106	    const info = listFixtures(this.#dir).find((f) => f.name === name);
107	    if (!info) throw new Error(`no fixture called ${name}`);
108	    this.#info = info;
109	    this.#records = readRecords(new URL(`${name}.jsonl`, this.#dir));
110	    this.#heartbeats = this.#records.some((r) => r.kind === 'msg' && (r.m as { type?: string } | undefined)?.type === 'heartbeat');
111	    this.#r = replayerFor(this.#records);
112	    this.#playing = false;
113	    this.#bookmarks = this.#findBookmarks();
114	  }
115	
116	  get offsetMs(): number { return this.#r.clock.now() - this.#r.start; }
117	  get durationMs(): number { return this.#r.end - this.#r.start; }
118	  get playing(): boolean { return this.#playing; }
119	
120	  play(): void { if (this.offsetMs >= this.durationMs) this.seek(0); this.#playing = true; }
121	  pause(): void { this.#playing = false; }
122	
123	  setSpeed(x: number): void {
124	    if (!(SPEEDS as readonly number[]).includes(x)) throw new Error(`speed ${x} is not one of ${SPEEDS.join(', ')}`);
125	    this.#speed = x;
126	  }
127	
128	  // Moves fixture time to `offsetMs` from the start. Going back replays from the start: the fleet
129	  // state only moves forward, as it does live.
130	  seek(offsetMs: number): void {
131	    const target = this.#r.start + Math.max(0, Math.min(offsetMs, this.durationMs));
132	    if (target < this.#r.clock.now()) this.#r = replayerFor(this.#records);
133	    this.#r.advanceTo(target);
134	  }
135	
136	  step(ms: number): void { this.seek(this.offsetMs + ms); }
137	
138	  // To the next bookmark, or the end.
139	  nextEvent(): void {
140	    const now = this.offsetMs;
141	    const mark = this.#bookmarks.find((b) => b.offsetMs > now)?.offsetMs ?? this.durationMs;
142	    this.seek(mark);
143	  }
144	
145	  // Wall time has passed; fixture time follows at the chosen speed while playing, and stops at the end.
146	  advanceWall(wallMs: number): void {
147	    if (!this.#playing || wallMs <= 0) return;
148	    this.seek(this.offsetMs + wallMs * this.#speed);
149	    if (this.offsetMs >= this.durationMs) this.#playing = false;
150	  }
151	
152	  frame(): Frame {
153	    const site = this.#r.fleet.site;
154	    return {
155	      player: {
156	        fixture: this.#info.name,
157	        shows: this.#info.shows,
158	        source: this.#info.source,
159	        startMs: this.#r.start,
160	        endMs: this.#r.end,
161	        offsetMs: this.offsetMs,
162	        playing: this.#playing,
163	        speed: this.#speed,
164	        atEnd: this.offsetMs >= this.durationMs,
165	        heartbeatsRecorded: this.#heartbeats,
166	        helloFrom: ownHello(this.#records) ? 'fixture' : 'this site, re-timed',
167	        bookmarks: this.#bookmarks,
168	      },
169	      site: site ? siteData(site) : null,
170	      snapshot: this.#r.fleet.snapshot(),
171	    };
172	  }
173	
174	  // The moments worth jumping to, found by replaying the whole fixture once: confidence changes
175	  // other than old, zone changes, battery warnings, controller restarts, the site link going down and
176	  // coming back, reconnects, and what the probe sent. A truck's confidence marks count once each per
177	  // kind, and its battery marks once per warning, so a thinned recording (weak-pack keeps other trucks
178	  // at 0.2 Hz, so they flicker silent) doesn't bury the moments that matter.
179	  #findBookmarks(): Bookmark[] {
180	    const marks: Bookmark[] = [];
181	    const once = new Set<string>();
182	    const mark = (key: string, text: string) => { if (!once.has(key)) { once.add(key); marks.push({ offsetMs: at(), text }); } };
183	    const r = replayerFor(this.#records);
184	    const at = () => r.clock.now() - r.start;
185	    r.fleet.subscribe((e) => {
186	      switch (e.type) {
187	        case 'confidence':
188	          if (e.to === 'contradicted') mark(`${e.vehicleId}:frozen`, `${e.vehicleId} data frozen`);
189	          else if (e.to === 'silent') mark(`${e.vehicleId}:silent`, `${e.vehicleId} silent`);
190	          else if (e.to === 'live' && (e.from === 'silent' || e.from === 'contradicted')) mark(`${e.vehicleId}:again`, `${e.vehicleId} reporting again`);
191	          break;
192	        case 'zone':
193	          // A hello lists every open zone; only real changes are worth a mark.
194	          if (e.status === 'OPEN' && !e.reason) break;
195	          marks.push({ offsetMs: at(), text: `${e.zoneId} ${e.status ?? 'status unknown'}${e.reason ? ` (${e.reason})` : ''}` });
196	          break;
197	        case 'battery':
198	          if (e.warning) mark(`${e.vehicleId}:battery:${e.warning}`, `${e.vehicleId} battery: ${e.message ?? e.warning}`);
199	          else if (e.drainHigh) mark(`${e.vehicleId}:drain`, `${e.vehicleId} battery: draining faster than the fleet`);
200	          break;
201	        case 'controller_restart': marks.push({ offsetMs: at(), text: `${e.vehicleId} controller restarted` }); break;
202	        default: break;
203	      }
204	    });
205	    let linkDown: boolean | null = null;
206	    for (let t = r.start; ; t = Math.min(t + BOOKMARK_SAMPLE_MS, r.end)) {
207	      r.advanceTo(t);
208	      if (this.#heartbeats) {
209	        const hb = r.fleet.snapshot().heartbeat;
210	        const down = hb.stale && hb.ageMs !== null;
211	        if (linkDown !== null && down !== linkDown) marks.push({ offsetMs: at(), text: down ? 'site link down (no heartbeat)' : 'site link back' });
212	        if (hb.ageMs !== null) linkDown = down;
213	      }
214	      if (t >= r.end) break;
215	    }
216	    for (const rec of this.#records) {
217	      if (rec.kind === 'sent') {
218	        const c = safeJson(rec.raw);
219	        if (c) marks.push({ offsetMs: rec.rx_ms! - r.start, text: `recorded: probe sent ${String(c.action)} to ${String(c.vehicle_id)}` });
220	      } else if (rec.kind === 'connected') marks.push({ offsetMs: rec.rx_ms! - r.start, text: `recorded: reconnect attempt ${String(rec.attempt ?? '')}` });
221	      else if (rec.kind === 'msg' && (rec.m as { type?: string })?.type === 'hello') marks.push({ offsetMs: rec.rx_ms! - r.start, text: 'hello (site snapshot)' });
222	    }
223	    marks.sort((a, b) => a.offsetMs - b.offsetMs);
224	    return marks.slice(0, MAX_BOOKMARKS);
225	  }
226	}
