228	function safeJson(s: unknown): Record<string, unknown> | null {
229	  try { return JSON.parse(String(s)) as Record<string, unknown>; } catch { return null; }
230	}
231	// HTTP for the fixture player: serves the Overview (src/ui/) and streams frames to it. Listens on
232	// localhost only. The browser's controls change what is replayed; nothing is ever sent to a gateway.
233	//
234	// No build step (task 6a): the browser imports the TypeScript modules in src/ directly, and this
235	// server strips their types on the way out with Node's module.stripTypeScriptTypes.
236	import { createServer, type IncomingMessage, type ServerResponse } from 'node:http';
237	import { readFile } from 'node:fs/promises';
238	import { stripTypeScriptTypes } from 'node:module';
239	import { extname, normalize, sep } from 'node:path';
240	import { fileURLToPath } from 'node:url';
241	import type { Clock, TimerHandle } from '../src/clock.ts';
242	import { listFixtures, Player, type Frame } from './player.ts';
243	
244	const SRC = fileURLToPath(new URL('../src/', import.meta.url));
245	const INDEX = 'ui/index.html';
246	const TICK_MS = 200; // frames while playing: 5 per second, the rate trucks report at
247	const IDLE_FRAME_MS = 1_000; // frames while paused, so the browser can tell the player is still there
248	
249	const TYPES: Record<string, string> = {
250	  '.ts': 'text/javascript; charset=utf-8',
251	  '.html': 'text/html; charset=utf-8',
252	  '.css': 'text/css; charset=utf-8',
253	};
254	
255	// stripTypeScriptTypes is marked experimental and warns once per process. The player is a dev tool;
256	// this one warning is dropped so the console shows only what matters. Any other warning still prints.
257	const emitWarning = process.emitWarning.bind(process);
258	process.emitWarning = ((w: string | Error, ...rest: unknown[]) => {
259	  if (String(typeof w === 'string' ? w : w.message).includes('stripTypeScriptTypes')) return;
260	  (emitWarning as (...a: unknown[]) => void)(w, ...rest);
261	}) as typeof process.emitWarning;
