269	export async function startPlayerServer(opts: { clock: Clock; fixture: string; port?: number; playing?: boolean }): Promise<PlayerServer> {
270	  const { clock } = opts;
271	  const player = new Player(opts.fixture);
272	  if (opts.playing) player.play();
273	  const streams = new Set<ServerResponse>();
274	  let lastWall = clock.now();
275	  let lastSent = -Infinity;
276	  let timer: TimerHandle | null = null;
277	
278	  const send = (f: Frame) => {
279	    const data = `data: ${JSON.stringify(f)}\n\n`;
280	    for (const s of streams) s.write(data);
281	    lastSent = clock.now();
282	  };
283	  const loop = () => {
284	    const now = clock.now();
285	    player.advanceWall(now - lastWall);
286	    lastWall = now;
287	    if (player.playing || now - lastSent >= IDLE_FRAME_MS) send(player.frame());
288	    timer = clock.setTimeout(loop, TICK_MS);
289	  };
290	  timer = clock.setTimeout(loop, TICK_MS);
291	
292	  const control = (body: Record<string, unknown>) => {
293	    switch (body.op) {
294	      case 'load': player.load(String(body.fixture)); break;
295	      case 'play': player.play(); break;
296	      case 'pause': player.pause(); break;
297	      case 'seek': player.seek(Number(body.offsetMs)); break;
298	      case 'step': player.step(Number(body.ms)); break;
299	      case 'next': player.nextEvent(); break;
300	      case 'speed': player.setSpeed(Number(body.speed)); break;
301	      default: throw new Error(`unknown op ${String(body.op)}`);
302	    }
303	    lastWall = clock.now();
304	    send(player.frame());
305	  };
306	
307	  const server = createServer((req, res) => {
308	    handle(req, res).catch((e: unknown) => reply(res, 500, 'text/plain', String(e instanceof Error ? e.message : e)));
309	  });
310	
311	  async function handle(req: IncomingMessage, res: ServerResponse): Promise<void> {
312	    const url = new URL(req.url ?? '/', 'http://localhost');
313	    if (req.method === 'GET' && url.pathname === '/api/stream') {
314	      res.writeHead(200, { 'content-type': 'text/event-stream', 'cache-control': 'no-store', connection: 'keep-alive' });
315	      streams.add(res);
316	      req.on('close', () => streams.delete(res));
317	      res.write(`data: ${JSON.stringify(player.frame())}\n\n`);
318	      return;
319	    }
320	    if (req.method === 'GET' && url.pathname === '/api/fixtures') return reply(res, 200, 'application/json', JSON.stringify(listFixtures()));
321	    if (req.method === 'POST' && url.pathname === '/api/control') {
322	      const body = JSON.parse(await readBody(req)) as Record<string, unknown>;
323	      try { control(body); } catch (e) { return reply(res, 400, 'text/plain', e instanceof Error ? e.message : String(e)); }
324	      return reply(res, 204, 'text/plain', '');
325	    }
326	    if (req.method !== 'GET') return reply(res, 405, 'text/plain', 'method not allowed');
327	    const rel = url.pathname === '/' ? INDEX : decodeURIComponent(url.pathname).replace(/^\/src\//, '');
328	    const path = normalize(SRC + rel);
329	    const type = TYPES[extname(path)];
330	    if (!path.startsWith(SRC) || path.split(sep).some((p) => p.startsWith('._') || p === '..') || !type) return reply(res, 404, 'text/plain', 'not found');
331	    let text: string;
332	    try { text = await readFile(path, 'utf8'); } catch { return reply(res, 404, 'text/plain', 'not found'); }
333	    if (extname(path) === '.ts') text = stripTypeScriptTypes(text);
334	    return reply(res, 200, type, text);
335	  }
336	
337	  await new Promise<void>((resolve) => server.listen(opts.port ?? 0, '127.0.0.1', resolve));
338	  const addr = server.address();
339	  const port = typeof addr === 'object' && addr ? addr.port : 0;
340	  return {
341	    url: `http://127.0.0.1:${port}/`,
342	    player,
343	    close: () => new Promise<void>((resolve) => {
344	      if (timer) clock.clearTimeout(timer);
345	      for (const s of streams) s.end();
346	      server.close(() => resolve());
347	      server.closeAllConnections();
348	    }),
349	  };
350	}
351	
352	function reply(res: ServerResponse, status: number, type: string, body: string): void {
353	  res.writeHead(status, { 'content-type': type, 'cache-control': 'no-store' });
354	  res.end(body);
355	}
356	
357	function readBody(req: IncomingMessage): Promise<string> {
358	  return new Promise((resolve, reject) => {
359	    let s = '';
360	    req.setEncoding('utf8');
361	    req.on('data', (c: string) => { s += c; if (s.length > 10_000) reject(new Error('body too large')); });
362	    req.on('end', () => resolve(s));
363	    req.on('error', reject);
364	  });
365	}
