1	/// <reference lib="dom" />
2	// The Overview in the browser: draws what src/ui/track.ts and src/ui/overview.ts compute from each
3	// frame, and nothing else. All decisions about words, order and shape live in those pure modules.
4	//
5	// Frames come from the fixture player now (player/server.ts) and from the service later, over the
6	// same shape: { player?, site, snapshot }. The browser keeps its own clock only to notice frames have
7	// stopped, so a stopped feed never looks current (UI.md principle 2).
8	import { SystemClock } from '../clock.ts';
9	import type { FleetSnapshot } from '../fleet.ts';
10	import { clearanceRows, fleetRows, serviceLink, siteLink, type LinkView } from './overview.ts';
11	import { trackModel, type SiteData, type TrackModel } from './track.ts';
12	
13	interface PlayerState {
14	  fixture: string; shows: string; source: string; startMs: number; endMs: number; offsetMs: number;
15	  playing: boolean; speed: number; atEnd: boolean; heartbeatsRecorded: boolean; helloFrom: string;
16	  bookmarks: Array<{ offsetMs: number; text: string }>;
17	}
18	interface Frame { player?: PlayerState; site: SiteData | null; snapshot: FleetSnapshot }
19	
20	const SERVICE_STALE_MS = 3_000; // the player sends a frame at least every second
21	const SPEEDS = [0.5, 1, 2, 5, 10, 30];
22	const clock = new SystemClock();
23	const $ = <T extends HTMLElement = HTMLElement>(id: string) => document.getElementById(id) as T;
24	const SVG = 'http://www.w3.org/2000/svg';
25	
26	let frame: Frame | null = null;
27	let lastFrameAt: number | null = null;
28	
29	// ---- small DOM helpers ----
30	
31	function el<K extends keyof HTMLElementTagNameMap>(tag: K, attrs: Record<string, string> = {}, ...kids: Array<Node | string | null>): HTMLElementTagNameMap[K] {
32	  const e = document.createElement(tag);
33	  for (const [k, v] of Object.entries(attrs)) e.setAttribute(k, v);
34	  for (const k of kids) if (k !== null) e.append(k);
35	  return e;
36	}
37	
38	function svg(tag: string, attrs: Record<string, string | number> = {}, ...kids: Array<Node | string>): SVGElement {
39	  const e = document.createElementNS(SVG, tag);
40	  for (const [k, v] of Object.entries(attrs)) e.setAttribute(k, String(v));
41	  for (const k of kids) e.append(k);
42	  return e;
43	}
44	
45	const clock2 = (ms: number) => { const s = Math.floor(ms / 1000); return `${Math.floor(s / 60)}:${String(s % 60).padStart(2, '0')}`; };
46	
47	// ---- links and banners ----
48	
49	function setLink(id: string, v: LinkView): void {
50	  const e = $(id);
51	  e.dataset.state = v.state;
52	  e.textContent = v.text;
53	}
54	
55	function renderLinks(): void {
56	  const since = lastFrameAt === null ? null : clock.now() - lastFrameAt;
57	  const service = serviceLink(since, SERVICE_STALE_MS);
58	  setLink('service-link', service);
59	  const site = frame ? siteLink(frame.snapshot, frame.player?.heartbeatsRecorded ?? true) : { state: 'down' as const, text: 'Site link: no data' };
60	  setLink('site-link', site);
61	  const aged = service.state === 'down' || site.state === 'down';
62	  document.body.classList.toggle('aged', aged);
63	  const banners: HTMLElement[] = [];
64	  if (service.state === 'down') banners.push(el('div', { class: 'banner down' }, `${service.text}. The picture below is not current.`));
65	  if (site.state === 'down') banners.push(el('div', { class: 'banner down' }, `${site.text}. Everything below is at least that old; ages keep counting.`));
66	  const p = frame?.player;
67	  if (p && !p.playing && service.state !== 'down') {
68	    banners.push(el('div', { class: 'banner note' }, p.atEnd ? 'End of the recording. Fixture time has stopped: ages are not counting.' : 'Paused. Fixture time has stopped: ages are not counting.'));
69	  }
70	  $('banners').replaceChildren(...banners);
71	}
72	
73	// ---- zone clearance ----
74	
75	function renderClearance(snap: FleetSnapshot): void {
76	  const rows = clearanceRows(snap);
77	  if (rows.length === 0) {
78	    $('clearance').replaceChildren(el('p', { class: 'none' }, 'No zone is closing or closed.'));
79	    return;
80	  }

180	
181	// ---- fleet table ----
182	
183	function renderRows(snap: FleetSnapshot): void {
184	  $('rows').replaceChildren(...fleetRows(snap).map((r) => el('tr', { class: r.dataKind, 'data-truck': r.vehicleId, 'data-kind': r.dataKind },
185	    el('td', { class: 'id' }, r.vehicleId),
186	    el('td', { class: 'data' }, r.data),
187	    el('td', { class: 'why' }, r.attention ?? ''),
188	    el('td', {}, r.state, r.fault ? el('span', { class: 'fault' }, r.fault) : null),
189	    el('td', {}, r.zone, r.zoneAlert ? el('br') : null, r.zoneAlert ? el('span', { class: 'zalert' }, r.zoneAlert) : null),
190	    el('td', {}, r.soc, ...r.socFlags.map((f) => el('span', { class: 'flag' }, f))),
191	    el('td', {}, r.control),
192	    el('td', { class: 'cmd', title: 'The command registry is not built yet' }, r.lastCommand),
193	  )));
194	}
195	
196	// ---- player controls ----
197	
198	async function control(body: Record<string, unknown>): Promise<void> {
199	  await fetch('/api/control', { method: 'POST', headers: { 'content-type': 'application/json' }, body: JSON.stringify(body) });
200	}
201	
202	function renderPlayer(p: PlayerState | undefined): void {
203	  const box = $('player');
204	  box.hidden = !p;
205	  if (!p) return;
206	  $('mode').textContent = `REPLAY · ${p.fixture}`;
207	  const fx = $<HTMLSelectElement>('fixture');
208	  if (fx.value !== p.fixture) fx.value = p.fixture;
209	  $('play').textContent = p.playing ? '⏸ Pause' : '▶ Play';
210	  $<HTMLSelectElement>('speed').value = String(p.speed);
211	  const seek = $<HTMLInputElement>('seek');
212	  seek.max = String(p.endMs - p.startMs);
213	  if (document.activeElement !== seek) seek.value = String(p.offsetMs);
214	  $('pos').textContent = `+${clock2(p.offsetMs)} / ${clock2(p.endMs - p.startMs)}`;
215	  const marks = $<HTMLSelectElement>('marks');
216	  const key = `${p.fixture}:${p.bookmarks.length}`;
217	  if (marks.dataset.key !== key) {
218	    marks.dataset.key = key;
219	    marks.replaceChildren(el('option', { value: '' }, 'Jump to…'), ...p.bookmarks.map((b) => el('option', { value: String(b.offsetMs) }, `+${clock2(b.offsetMs)} ${b.text}`)));
220	  }
221	  $('shows').textContent = `${p.shows}${p.helloFrom === 'fixture' ? '' : ' (No hello in this recording: replayed on this site\'s route, every zone open at the start.)'}`;
222	}
223	
224	async function setupPlayer(): Promise<void> {
225	  const list = await (await fetch('/api/fixtures')).json() as Array<{ name: string }>;
226	  $('fixture').replaceChildren(...list.map((f) => el('option', { value: f.name }, f.name)));
227	  $('speed').replaceChildren(...SPEEDS.map((s) => el('option', { value: String(s) }, `${s}×`)));
228	  $('fixture').addEventListener('change', (e) => void control({ op: 'load', fixture: (e.target as HTMLSelectElement).value }));
229	  $('restart').addEventListener('click', () => void control({ op: 'seek', offsetMs: 0 }));
230	  $('play').addEventListener('click', () => void control({ op: frame?.player?.playing ? 'pause' : 'play' }));
231	  $('step1').addEventListener('click', () => void control({ op: 'step', ms: 1_000 }));
232	  $('step5').addEventListener('click', () => void control({ op: 'step', ms: 5_000 }));
233	  $('next').addEventListener('click', () => void control({ op: 'next' }));
234	  $('speed').addEventListener('change', (e) => void control({ op: 'speed', speed: Number((e.target as HTMLSelectElement).value) }));
235	  $('seek').addEventListener('change', (e) => void control({ op: 'seek', offsetMs: Number((e.target as HTMLInputElement).value) }));
236	  $('marks').addEventListener('change', (e) => {
237	    const v = (e.target as HTMLSelectElement).value;
238	    if (v !== '') void control({ op: 'seek', offsetMs: Number(v) });
239	  });
240	  // ?fixture=name&t=ms opens a recording at a moment, paused: for links and screenshots.
241	  const q = new URLSearchParams(location.search);
242	  if (q.get('fixture')) await control({ op: 'load', fixture: q.get('fixture') });
243	  if (q.get('t')) await control({ op: 'seek', offsetMs: Number(q.get('t')) });
244	}
245	
246	// ---- sound ----
247	
248	function setupSound(): void {
249	  const b = $('sound');
250	  b.addEventListener('click', () => {
251	    const Ctx = (window as unknown as { AudioContext?: typeof AudioContext }).AudioContext;
252	    if (!Ctx) return;
253	    void new Ctx().resume().then(() => { b.dataset.armed = 'true'; b.textContent = 'Sound armed'; });
254	  });
255	}
256	
257	// ---- main ----
258	
259	function render(): void {
260	  renderLinks();
261	  if (!frame) return;
262	  renderPlayer(frame.player);
263	  $('site-id').textContent = frame.snapshot.siteId ?? 'no site yet';
264	  renderClearance(frame.snapshot);
265	  if (frame.site) renderTrack(frame.site, frame.snapshot);
266	  else $('track').replaceChildren(el('p', { class: 'none' }, 'No route yet: waiting for the site description (hello).'));
267	  renderRows(frame.snapshot);
268	}
269	
270	function connect(): void {
271	  const es = new EventSource('/api/stream');
272	  es.onmessage = (e) => {
273	    frame = JSON.parse(e.data as string) as Frame;
274	    lastFrameAt = clock.now();
275	    render();
276	  };
277	}
278	
279	const watch = () => { renderLinks(); clock.setTimeout(watch, 500); };
280	
281	setupSound();
282	void setupPlayer().then(connect);
283	watch();
284	let resizeTimer: ReturnType<typeof clock.setTimeout> | null = null;
285	window.addEventListener('resize', () => {
286	  if (resizeTimer) clock.clearTimeout(resizeTimer);
287	  resizeTimer = clock.setTimeout(render, 100);
288	});
289	document.body.dataset.ready = 'true';

