// Scratch: drives the running service by hand. Not committed.
import WebSocket from 'ws';
const base = 'http://127.0.0.1:8099';
async function login(u: string, p: string): Promise<string> {
  const r = await fetch(`${base}/login`, { method: 'POST', redirect: 'manual', headers: { origin: base, 'content-type': 'application/x-www-form-urlencoded' }, body: new URLSearchParams({ username: u, password: p }) });
  return r.headers.get('set-cookie')!.split(';')[0]!;
}
const priya = await login('priya', 'haul-priya-demo');
const marta = await login('marta', 'haul-marta-demo');
const open = (cookie: string) => new Promise<WebSocket>((res) => { const w = new WebSocket(`ws://127.0.0.1:8099/api/live`, { headers: { origin: base, cookie } }); w.on('open', () => res(w)); });
const p = await open(priya);
const m = await open(marta);
const got: any[] = [];
